/** Genuine stored IDs keep optional dictionary hashes out of inline lexical and stale-association domains. */
class ValueStoreHashIdDomainContractTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@EnumSource(Profile.class)
	void realStoredTermsKeepTheirSemanticHashesAndDictionaryAssociations(Profile profile,
			@TempDir File directory) throws Exception {
		profile.initializeLegacyProperties(directory);
		ValueStore values = new ValueStore(directory, profile.config());
		try {
			List<Value> terms = List.of(VF.createLiteral("42", CoreDatatype.XSD.INTEGER),
					VF.createLiteral(3.25d), VF.createLiteral("abc"),
					VF.createLiteral("a dictionary string that is too long to inline"),
					VF.createLiteral("007", CoreDatatype.XSD.INT),
					VF.createLiteral("custom", VF.createIRI("urn:hash-domain:datatype")),
					VF.createLiteral("hello", "en"), VF.createIRI("urn:hash-domain:iri"),
					VF.createBNode("hash-domain-blank"));
			values.startTransaction(true);
			long[] ids = new long[terms.size()];
			for (int i = 0; i < terms.size(); i++) {
				ids[i] = values.storeValue(terms.get(i));
			}
			values.commit();
			ValueStoreRevision revision = values.getRevision();
			long revisionId = revision.getRevisionId();
			for (int i = 0; i < terms.size(); i++) {
				Value term = terms.get(i);
				long id = ids[i];
				assertNotEquals(LmdbValue.UNKNOWN_ID, id);
				LmdbValue cold = values.getLazyValue(id);
				// This is the original real failure surface: hashing a genuine stored inline literal, not a
				// fabricated ID or a direct arithmetic exception probe.
				assertEquals(term.hashCode(), cold.hashCode(), term.toString());
				assertEquals(term, cold);
				assertEquals(cold, term);
				assertTrue(new HashSet<>(List.of(term)).contains(cold));
				if (ValueIds.isInlined(id)) {
					assertTrue(term instanceof Literal);
					assertEquals(0, values.getStoredHash(id, revisionId));
					values.storeHash(id, term.hashCode(), revisionId);
					assertEquals(0, values.getStoredHash(id, revisionId));
					assertEquals(0, values.getStoredHash(id));
					values.clearStoredHash(id);
				} else {
					assertTrue(ValueIds.isReference(id));
					values.storeHash(id, term.hashCode(), revisionId);
					assertEquals(term.hashCode(), values.getStoredHash(id, revisionId));
					values.clearStoredHash(id);
					assertEquals(0, values.getStoredHash(id, revisionId));
					values.storeHash(id, term.hashCode(), revisionId);
				}
				assertEquals(term.hashCode(), cold.hashCode());
				assertEquals(term, values.getValue(id));
			}
			assertEquals(0, values.getStoredHash(LmdbValue.UNKNOWN_ID, revisionId));
		} finally {
			values.close();
		}
	}

	@Test
	void fileSlotArithmeticDeclinesARealStoredInlineIdOutsideItsAddressDomain(@TempDir File directory)
			throws Exception {
		File dictionary = new File(directory, "dictionary");
		ValueStore values = new ValueStore(dictionary, new LmdbStoreConfig().setInlineLiterals(true)
				.setOrderedNumericIds(true));
		long id;
		try {
			values.startTransaction(true);
			id = values.storeValue(VF.createLiteral("42", CoreDatatype.XSD.INTEGER));
			values.commit();
			assertTrue(ValueIds.isInlined(id));
			assertTrue(id > Long.MAX_VALUE / Integer.BYTES,
					"the actual ordered inline ID is not representable as a file-slot byte offset");
		} finally {
			values.close();
		}
		File cacheDirectory = new File(directory, "raw-slot-file");
		Files.createDirectories(cacheDirectory.toPath());
		try (ValueStoreHashFile hashes = new ValueStoreHashFile(cacheDirectory)) {
			// This file abstraction accepts numeric slots; slot 1 is its existing positive control, not an RDF ID.
			hashes.put(1L, 1234);
			long before = Files.size(new File(cacheDirectory, ValueStoreHashFile.FILE_NAME).toPath());
			assertEquals(0, hashes.get(id));
			hashes.put(id, 5678);
			hashes.clear(id);
			assertEquals(1234, hashes.get(1L));
			assertEquals(before, Files.size(new File(cacheDirectory, ValueStoreHashFile.FILE_NAME).toPath()));
		}
	}

	@Test
	void staleRevisionCannotReadOrReplaceTheNewGenerationHash(@TempDir File directory) throws Exception {
		ValueStore values = new ValueStore(directory, new LmdbStoreConfig().setInlineLiterals(false)
				.setValueHashCacheEnabled(true));
		try {
			Literal oldTerm = VF.createLiteral("old generation dictionary term");
			long oldId = store(values, oldTerm);
			ValueStoreRevision oldRevision = values.getRevision();
			values.storeHash(oldId, oldTerm.hashCode(), oldRevision.getRevisionId());
			assertEquals(oldTerm.hashCode(), oldRevision.getStoredHash(oldId));
			values.clear();

			Literal newTerm = VF.createLiteral("new generation dictionary term");
			long newId = store(values, newTerm);
			ValueStoreRevision current = values.getRevision();
			assertNotEquals(oldRevision.getRevisionId(), current.getRevisionId());
			values.storeHash(newId, newTerm.hashCode(), current.getRevisionId());
			assertEquals(newTerm.hashCode(), current.getStoredHash(newId));
			assertEquals(0, oldRevision.getStoredHash(newId));
			oldRevision.storeHash(newId, oldTerm.hashCode());
			assertEquals(newTerm.hashCode(), current.getStoredHash(newId));
			LmdbLiteral resolved = (LmdbLiteral) values.getLazyValue(newId);
			assertEquals(newTerm.hashCode(), resolved.hashCode());
			assertEquals(newTerm, resolved);
		} finally {
			values.close();
		}
	}

	private static long store(ValueStore values, Value value) throws Exception {
		values.startTransaction(true);
		long id = values.storeValue(value);
		values.commit();
		return id;
	}

	private enum Profile {
		LEGACY_REFERENCES(true, false, false),
		LEGACY_INLINE(true, true, false),
		CURRENT_REFERENCES(false, false, true),
		CURRENT_ORDERED_INLINE(false, true, true),
		CURRENT_ZIGZAG_INLINE(false, true, false);

		final boolean legacy;
		final boolean inline;
		final boolean ordered;

		Profile(boolean legacy, boolean inline, boolean ordered) {
			this.legacy = legacy;
			this.inline = inline;
			this.ordered = ordered;
		}

		LmdbStoreConfig config() {
			return new LmdbStoreConfig().setInlineLiterals(inline)
					.setOrderedNumericIds(ordered)
					.setValueHashCacheEnabled(true);
		}

		void initializeLegacyProperties(File directory) throws Exception {
			if (legacy) {
				Files.createDirectories(directory.toPath());
				new StoreProperties(directory).setVersion("2")
						.setTripleTermIndexes("spoc,cspo")
						.setInlineLiterals(inline)
						.save();
			}
		}
	}
}
